    when checklist_setting->''funclist''->1->>''func_class'' = ''1'' then ''治療条件''
    when checklist_setting->''funclist''->1->>''func_class'' = ''2'' then ''医療材料''
    else ''通常リスト''
  end as func_code_name_2
